141	void PortExtension::measurementCompleted(std::vector<DeviceDriver::VNAMeasurement> m)
142	{
143	    if(m.size() > 0) {
144	        double last_phase = 0.0;
145	        double phasediff_sum = 0.0;
146	        vector<double> att_x, att_y;
147	        double avg_x = 0.0, avg_y = 0.0;
148	        for(auto p : m) {
149	            // grab correct measurement
150	            QString name = "S"+QString::number(port)+QString::number(port);
151	            auto reflection = p.measurements[name];
152	            // remove calkit if specified
153	            if(!isIdeal) {
154	                complex<double> calStandard = 1.0;
155	                auto comp = isOpen ? CalStandard::Virtual::Type::Open : CalStandard::Virtual::Type::Short;
156	                for(auto s : kit->getStandards()) {
157	                    if(s->getType() == comp) {
158	                        calStandard = static_cast<CalStandard::OnePort*>(s)->toS11(p.frequency);
159	                    }
160	                }
161	                // remove effect of calibration standard
162	                reflection /= calStandard;
163	            }
164	            // sum phase differences to previous point
165	            auto phase = arg(reflection);
166	            if(p.pointNum == 0) {
167	                last_phase = phase;
168	            } else {
169	                auto phasediff = phase - last_phase;
170	                last_phase = phase;
171	                if(phasediff > M_PI) {
172	                    phasediff -= 2 * M_PI;
173	                } else if(phasediff <= -M_PI) {
174	                    phasediff += 2 * M_PI;
175	                }
176	                phasediff_sum += phasediff;
177	            }
178	
179	            double x = sqrt(p.frequency / m.back().frequency);
180	            double y = Util::SparamTodB(reflection);
181	            att_x.push_back(x);
182	            att_y.push_back(y);
183	            avg_x += x;
184	            avg_y += y;
185	        }
186	        auto phase = phasediff_sum / (m.size() - 1);
187	        auto freq_diff = m[1].frequency - m[0].frequency;
188	        auto delay = -phase / (2 * M_PI * freq_diff);
189	        // measured delay is two-way but port extension expects one-way
190	        delay /= 2;
191	
192	        // calculate linear regression with transformed square root model
193	        avg_x /= m.size();
194	        avg_y /= m.size();
195	        double sum_top = 0.0;
196	        double sum_bottom = 0.0;
197	        for(unsigned int i=0;i<att_x.size();i++) {
198	            sum_top += (att_x[i] - avg_x)*(att_y[i] - avg_y);
199	            sum_bottom += (att_x[i] - avg_x)*(att_x[i] - avg_x);
200	        }
201	        double beta = sum_top / sum_bottom;
202	        double alpha = avg_y - beta * avg_x;
203	
204	        double DCloss = -alpha / 2;
205	        double loss = -beta / 2;
206	        double freq = m.back().frequency;
207	        ui->Time->setValue(delay);
208	        ui->DCloss->setValue(DCloss);
209	        ui->Loss->setValue(loss);
210	        ui->Frequency->setValue(freq);
211	    }
212	}
