33	
34	        Tparam inv1, inv2;
35	        if(p.frequency < points.front().freq) {
36	            inv1 = points.front().inverseP1;
37	            inv2 = points.front().inverseP2;
38	        } else if(p.frequency > points.back().freq) {
39	            inv1 = points.back().inverseP1;
40	            inv2 = points.back().inverseP2;
41	        } else {
42	            // find correct measurement point
43	            auto point = lower_bound(points.begin(), points.end(), p.frequency, [](Point p, uint64_t freq) -> bool {
44	                return p.freq < freq;
45	            });
46	            if(point->freq == p.frequency) {
47	                inv1 = point->inverseP1;
48	                inv2 = point->inverseP2;
49	            } else {
50	                // need to interpolate
51	                auto high = point;
52	                point--;
53	                auto low = point;
54	                double alpha = (p.frequency - low->freq) / (high->freq - low->freq);
55	                inv1 = low->inverseP1 * (1 - alpha) + high->inverseP1 * alpha;
56	                inv2 = low->inverseP2 * (1 - alpha) + high->inverseP2 * alpha;
57	            }
58	        }
59	        // perform correction
60	        Tparam corrected = inv1*meas*inv2;
61	        // transform back into S parameters
62	        p.fromSparam(Sparam(corrected), {port1, port2});
63	    }
64	}
