230	void TwoThru::fromJSON(nlohmann::json j)
231	{
232	    nlohmann::json jpoints;
233	    if(j.is_array()) {
234	        // old format, containing the points as an array in the root json
235	        jpoints = j;
236	        port1 = 1;
237	        port2 = 2;
238	    } else {
239	        port1 = j.value("port1", 1);
240	        port2 = j.value("port2", 2);
241	        if(j.contains("points")) {
242	            jpoints = j["points"];
243	        } else {
244	            // missing points
245	            jpoints = nlohmann::json();
246	        }
247	    }
248	    points.clear();
249	    for(auto jp : jpoints) {
250	        Point p;
251	        p.freq = jp.value("frequency", 0.0);
252	        p.inverseP1.set(1,1, complex<double>(jp.value("p1_11_r", 0.0), jp.value("p1_11_i", 0.0)));
253	        p.inverseP1.set(1,2, complex<double>(jp.value("p1_12_r", 0.0), jp.value("p1_12_i", 0.0)));
254	        p.inverseP1.set(2,1, complex<double>(jp.value("p1_21_r", 0.0), jp.value("p1_21_i", 0.0)));
255	        p.inverseP1.set(2,2, complex<double>(jp.value("p1_22_r", 0.0), jp.value("p1_22_i", 0.0)));
256	        p.inverseP2.set(1,1, complex<double>(jp.value("p2_11_r", 0.0), jp.value("p2_11_i", 0.0)));
257	        p.inverseP2.set(1,2, complex<double>(jp.value("p2_12_r", 0.0), jp.value("p2_12_i", 0.0)));
258	        p.inverseP2.set(2,1, complex<double>(jp.value("p2_21_r", 0.0), jp.value("p2_21_i", 0.0)));
259	        p.inverseP2.set(2,2, complex<double>(jp.value("p2_22_r", 0.0), jp.value("p2_22_i", 0.0)));
260	        points.push_back(p);
261	    }
262	}
