264	std::vector<TwoThru::Point> TwoThru::calculateErrorBoxes(std::vector<DeviceDriver::VNAMeasurement> data_2xthru)
265	{
266	    // calculate error boxes, see https://www.freelists.org/post/si-list/IEEE-P370-Opensource-Deembedding-MATLAB-functions
267	    // create vectors of S parameters
268	    vector<complex<double>> S11, S12, S21, S22;
269	    vector<double> f;
270	
271	    // remove DC point if present
272	    if(data_2xthru[0].frequency == 0) {
273	        data_2xthru.erase(data_2xthru.begin());
274	    }
275	
276	    data_2xthru = interpolateEvenFrequencySteps(data_2xthru);
277	
278	    for(auto m : data_2xthru) {
279	        if(m.frequency == 0) {
280	            // ignore possible DC point
281	            continue;
282	        }
283	        auto S = m.toSparam().reduceTo({port1, port2});
284	        S11.push_back(S.get(1,1));
285	        S12.push_back(S.get(1,2));
286	        S21.push_back(S.get(2,1));
287	        S22.push_back(S.get(2,2));
288	        f.push_back(m.frequency);
289	    }
290	    auto n = f.size();
291	
292	    auto makeSymmetric = [](const vector<complex<double>> &in) -> vector<complex<double>> {
293	        auto abs_DC = 2.0 * abs(in[0]) - abs(in[1]);
294	        auto phase_DC = 2.0 * arg(in[0]) - arg(in[1]);
295	        auto DC = polar(abs_DC, phase_DC);
296	        vector<complex<double>> ret;
297	        ret.push_back(DC);
298	        // add non-symmetric part
299	        ret.insert(ret.end(), in.begin(), in.end());
300	        // add flipped complex conjugate values
301	        for(auto it = in.rbegin(); it != in.rend(); it++) {
302	            ret.push_back(conj(*it));
303	        }
304	        return ret;
305	    };
306	
307	    auto makeRealAndScale = [](vector<complex<double>> &in) {
308	        for(unsigned int i=0;i<in.size();i++) {
309	            in[i] = real(in[i]) / in.size();
310	        }
311	    };
312	
313	    // S parameter error boxes
314	    vector<Sparam> data_side1, data_side2;
315	
316	    {
317	        auto p112x = makeSymmetric(S11);
318	        auto p212x = makeSymmetric(S21);
319	
320	        // transform into time domain and calculate step responses
321	        auto t112x = p112x;
322	        Fft::transform(t112x, true);
323	        makeRealAndScale(t112x);
324	        Fft::shift(t112x, false);
325	        partial_sum(t112x.begin(), t112x.end(), t112x.begin());
326	        auto t212x = p212x;
327	        Fft::transform(t212x, true);
328	        makeRealAndScale(t212x);
329	        Fft::shift(t212x, false);
330	        partial_sum(t212x.begin(), t212x.end(), t212x.begin());
331	
332	        // find the midpoint of the trace
333	        double threshold = 0.5*real(t212x.back());
334	        auto mid = lower_bound(t212x.begin(), t212x.end(), threshold, [](complex<double> p, double c) -> bool {
335	                return real(p) < c;
336	        }) - t212x.begin();
337	
338	        // mask step response
339	        vector<complex<double>> t111xStep(2*n + 1, 0.0);
340	        copy(t112x.begin() + n, t112x.begin() + mid, t111xStep.begin() + n);
341	        Fft::shift(t111xStep, true);
342	        // create impulse response from masked step response
343	        adjacent_difference(t111xStep.begin(), t111xStep.end(), t111xStep.begin());
344	        Fft::transform(t111xStep, false);
345	        auto &p111x = t111xStep;
346	
347	        // calculate p221x and p211x
348	        vector<complex<double>> p221x;
349	        vector<complex<double>> p211x;
350	        double k = 1.0;
351	        complex<double> test, last_test;
352	        for(unsigned int i=0;i<p112x.size();i++) {
353	            p221x.push_back((p112x[i]-p111x[i])/p212x[i]);
354	            test = sqrt(p212x[i]*(1.0-p221x[i]*p221x[i]));
355	            if(i > 0) {
356	                // according to the octave script, the next line should be if(arg(test) - arg(last_test) > 0)
357	                // but that leads to 180° degree phase shift and also doesn't make much sense:
358	                // we want to figure out the correct sign for the root so that no phase jumps occur. The
359	                // phase difference from one to the next point is allowed to be positive, it just should be smaller
360	                // than PI/2 (otherwise we got the wrong sign for the root)
361	                if(abs(arg(test) - arg(last_test)) > M_PI / 2) {
362	                    k = -k;
363	                }
364	                qDebug() << "angle at point" << i << "(" << arg(test) - arg(last_test) << ")";
365	            }
366	            last_test = test;
367	            p211x.push_back(k*test);
368	        }
369	
370	        // create S parameter errorbox
371	        for(unsigned int i=1;i<=n;i++) {
372	            data_side1.push_back(Sparam(p111x[i], p211x[i], p211x[i], p221x[i]));
373	        }
374	    }
375	
376	    // same thing for error box 2. Variable names get a bit confusing because they are viewed from port 2 (S22 is now called p112x, ...).
377	    // All variable names follow https://gitlab.com/IEEE-SA/ElecChar/P370/-/blob/master/TG1/IEEEP3702xThru_Octave.m
378	    {
379	        auto p112x = makeSymmetric(S22);
380	        auto p212x = makeSymmetric(S12);
381	
382	        // transform into time domain and calculate step responses
383	        auto t112x = p112x;
384	        Fft::transform(t112x, true);
385	        makeRealAndScale(t112x);
386	        Fft::shift(t112x, false);
387	        partial_sum(t112x.begin(), t112x.end(), t112x.begin());
388	        auto t212x = p212x;
389	        Fft::transform(t212x, true);
390	        makeRealAndScale(t212x);
391	        Fft::shift(t212x, false);
392	        partial_sum(t212x.begin(), t212x.end(), t212x.begin());
393	
394	        // find the midpoint of the trace
395	        double threshold = 0.5*real(t212x.back());
396	        auto mid = lower_bound(t212x.begin(), t212x.end(), threshold, [](complex<double> p, double c) -> bool {
397	                return real(p) < c;
398	        }) - t212x.begin();
399	
400	        // mask step response
401	        vector<complex<double>> t111xStep(2*n + 1, 0.0);
402	        copy(t112x.begin() + n, t112x.begin() + mid, t111xStep.begin() + n);
403	        Fft::shift(t111xStep, true);
404	        // create impulse response from masked step response
405	        adjacent_difference(t111xStep.begin(), t111xStep.end(), t111xStep.begin());
406	        Fft::transform(t111xStep, false);
407	        auto &p111x = t111xStep;
408	
409	        // calculate p221x and p211x
410	        vector<complex<double>> p221x;
411	        vector<complex<double>> p211x;
412	        double k = 1.0;
413	        complex<double> test, last_test;
414	        for(unsigned int i=0;i<p112x.size();i++) {
415	            p221x.push_back((p112x[i]-p111x[i])/p212x[i]);
416	            test = sqrt(p212x[i]*(1.0-p221x[i]*p221x[i]));
417	            if(i > 0) {
418	                if(abs(arg(test) - arg(last_test)) > M_PI / 2) {
419	                    k = -k;
420	                }
421	            }
422	            last_test = test;
423	            p211x.push_back(k*test);
424	        }
425	
426	        // create S parameter errorbox
427	        for(unsigned int i=1;i<=n;i++) {
428	            data_side2.push_back(Sparam(data_side1[i-1].get(2,2), p211x[i], p211x[i], p111x[i]));
429	            data_side1[i-1].set(2,2, p221x[i]);
430	        }
431	    }
432	
433	    // got the error boxes, convert to T parameters and invert
434	    vector<Point> ret;
435	    for(unsigned int i=0;i<n;i++) {
436	        Point p;
437	        p.freq = f[i];
438	        p.inverseP1 = Tparam(data_side1[i]).inverse();
439	        p.inverseP2 = Tparam(data_side2[i]).inverse();
440	        ret.push_back(p);
441	    }
442	    return ret;
443	}
444	
445	std::vector<TwoThru::Point> TwoThru::calculateErrorBoxes(std::vector<DeviceDriver::VNAMeasurement> data_2xthru, std::vector<DeviceDriver::VNAMeasurement> data_fix_dut_fix, double z0)
446	{
447	    vector<Point> ret;
448	
449	    if(data_2xthru.size() != data_fix_dut_fix.size()) {
450	        InformationBox::ShowMessageBlocking("Unable to calculate", "The DUT and 2xthru measurements do not have the same amount of points, calculation not possible");
451	        return ret;
452	    }
453	
454	    // check if frequencies are the same (measurements must be taken with identical span settings)
455	    for(unsigned int i=0;i<data_2xthru.size();i++) {
456	        if(abs((long int)data_2xthru[i].frequency - (long int)data_fix_dut_fix[i].frequency) > (double) data_2xthru[i].frequency / 1e9) {
457	            InformationBox::ShowMessageBlocking("Unable to calculate", "The DUT and 2xthru measurements do not have identical frequencies for all points, calculation not possible");
458	            return ret;
459	        }
460	    }
461	
462	    data_2xthru = interpolateEvenFrequencySteps(data_2xthru);
463	    data_fix_dut_fix = interpolateEvenFrequencySteps(data_fix_dut_fix);
464	
465	    // Variable names and order of calulation follows https://gitlab.com/IEEE-SA/ElecChar/P370/-/blob/master/TG1/IEEEP370Zc2xThru_Octave.m as close as possible
466	    vector<Sparam> p;
467	    vector<double> f;
468	    for(auto d : data_2xthru) {
469	        p.push_back(d.toSparam().reduceTo({port1, port2}));
470	        f.push_back(d.frequency);
471	    }
472	    auto data_2xthru_Sparam = p;
473	    vector<Sparam> data_fix_dut_fix_Sparam;
474	    for(auto d : data_fix_dut_fix) {
475	        data_fix_dut_fix_Sparam.push_back(d.toSparam().reduceTo({port1, port2}));
476	    }
477	
478	    // grabbing S21
479	    vector<complex<double>> s212x;
480	    for(auto s : p) {
481	        s212x.push_back(s.get(2,1));
482	    }
483	
484	    // get the attenuation and phase constant per length
485	    vector<complex<double>> gamma;
486	    double last_angle = 0.0;
487	    for(auto s : s212x) {
488	        // unwrap phase
489	        double angle = arg(s);
490	        while(angle - last_angle > M_PI) {
491	            angle -= 2 * M_PI;
492	        }
493	        while(angle - last_angle < -M_PI) {
494	            angle += 2 * M_PI;
495	        }
496	        last_angle = angle;
497	        double beta_per_length = -angle;
498	        double alpha_per_length = 20 * log10(abs(s))/-8.686;
499	
500	        // assume no bandwidth limit (==0)
501	        gamma.push_back(complex<double>(alpha_per_length, beta_per_length));
502	    }
503	
504	    // helper function lambdas
505	    auto makeSymmetric = [](const vector<complex<double>> &in) -> vector<complex<double>> {
506	        auto ret = in;
507	        for(auto it = in.rbegin();it != in.rend();it++) {
508	            ret.push_back(conj(*it));
509	        }
510	        // went one step too far, remove the DC point from the symmetric data
511	        ret.pop_back();
512	        return ret;
513	    };
514	
515	    auto makeRealAndScale = [](vector<complex<double>> &in) {
516	        for(unsigned int i=0;i<in.size();i++) {
517	            in[i] = real(in[i]) / in.size();
518	        }
519	    };
520	
521	    auto DC2 = [=](const vector<complex<double>> &s, const vector<double> &f) -> complex<double> {
522	        auto simple_filter = [](const vector<double> &f, double f0) -> vector<complex<double>> {
523	            vector<complex<double>> ret;
524	            for(auto v : f) {
525	                ret.push_back(1.0/complex<double>(1.0, pow(v/f0, 4)));
526	            }
527	            return ret;
528	        };
529	
530	        complex<double> DCpoint = 0.002; // seed for the algorithm
531	        double err = 1; // error seed
532	        double allowedError = 1e-10; // allowable error
533	        long cnt = 0;
534	        auto df = f[1] - f[0];
535	        auto n = f.size();
536	        unsigned int ts = round((-3e-9) / ((2.0/df)/(n*2+1)) + (n*2+1)/2);
537	        auto Hr = simple_filter(f, f.back()/2);
538	        while (err > allowedError) {
539	            vector<complex<double>> f1;
540	            f1.push_back(DCpoint);
541	            for(unsigned int i=0;i<n;i++) {
542	                f1.push_back(s[i] * Hr[i]);
543	            }
544	            auto h1 = makeSymmetric(f1);
545	            Fft::transform(h1, true);
546	            makeRealAndScale(h1);
547	            Fft::shift(h1, false);
548	            partial_sum(h1.begin(), h1.end(), h1.begin());
549	
550	            vector<complex<double>> f2;
551	            f2.push_back(DCpoint+0.001);
552	            for(unsigned int i=0;i<n;i++) {
553	                f2.push_back(s[i] * Hr[i]);
554	            }
555	            auto h2 = makeSymmetric(f2);
556	            Fft::transform(h2, true);
557	            makeRealAndScale(h2);
558	            Fft::shift(h2, false);
559	            partial_sum(h2.begin(), h2.end(), h2.begin());
560	
561	            auto m = (h2[ts]-h1[ts])/0.001;
562	            auto b = h1[ts] - m*DCpoint;
563	            DCpoint = (0.0 - b) / m;
564	            err = abs(h1[ts] - 0.0);
565	            cnt++;
566	        }
567	
568	        return DCpoint;
569	    };
570	
571	    auto makeTL = [](const vector<complex<double>> &gamma, double l, complex<double> zLine, complex<double> z0) -> vector<Sparam> {
572	        vector<Sparam> ret;
573	        for(auto g : gamma) {
574	            auto s11 = ((zLine*zLine-z0*z0)*sinh(g*l))/((zLine*zLine+z0*z0)*sinh(g*l)+2.0*z0*zLine*cosh(g*l));
575	            auto s21 = (2.0*z0*zLine)/((zLine*zLine + z0*z0)*sinh(g*l)+2.0*z0*zLine*cosh(g*l));
576	            ret.push_back(Sparam(s11, s21, s21, s11));
577	        }
578	        return ret;
579	    };
580	
581	    auto hybrid = [](const vector<Sparam> &errorbox, const vector<Sparam> &data_2xthru, const vector<double> &freq_2xthru) -> vector<Sparam> {
582	        // taking the errorbox created by peeling and using it only for e00 and e11
583	
584	        // grab s11 and s22 of errorbox model
585	        vector<complex<double>> s111x, s221x;
586	        for(auto s : errorbox) {
587	            s111x.push_back(s.get(1,1));
588	            s221x.push_back(s.get(2,2));
589	        }
590	
591	        // grab s21 of the 2x thru measurement
592	        vector<complex<double>> s212x;
593	        for(auto s : data_2xthru) {
594	            s212x.push_back(s.get(2,1));
595	        }
596	        auto f = freq_2xthru;
597	
598	        double k = 1.0;
599	        complex<double> test, last_test;
600	        vector<complex<double>> s211x;
601	        vector<Sparam> ret;
602	        for(unsigned int i=0;i<f.size();i++) {
603	            test = sqrt(s212x[i]*(1.0-s221x[i]*s221x[i]));
604	            if(i > 0) {
605	                if(abs(arg(test) - arg(last_test)) > M_PI / 2) {
606	                    k = -k;
607	                }
608	            }
609	            last_test = test;
610	            s211x.push_back(k*test);
611	
612	            // create the error box and make the s-parameter block
613	            ret.push_back(Sparam(s111x[i], s211x[i], s211x[i], s221x[i]));
614	        }
615	        return ret;
616	    };
617	
618	    auto makeErrorbox = [=](vector<Sparam> data_dut, const vector<Sparam> &data_2xthru, const vector<double> &freq_2xthru, const vector<complex<double>> &gamma, complex<double> z0) -> vector<Sparam> {
619	        auto f = freq_2xthru;
620	        auto n = f.size();
621	
622	        vector<complex<double>> s212x;
623	        // add the DC point
624	        s212x.push_back(1.0);
625	        for(auto p : data_2xthru) {
626	            s212x.push_back(p.get(2,1));
627	        }
628	        // extract the mid point from the 2x thru
629	        auto t212x = makeSymmetric(s212x);
630	        Fft::transform(t212x, true);
631	        makeRealAndScale(t212x);
632	        auto x = max_element(t212x.begin(), t212x.end(), [](complex<double> a, complex<double> b) -> bool {
633	            return abs(a) < abs(b);
634	        }) - t212x.begin() + 1;
635	
636	        // define the relative length
637	        double l = 1.0/(2*x);
638	
639	        // peel away the fixture and create the errorbox
640	
641	        // create the errorbox seed (a perfect transmission line with no delay)
642	        vector<ABCDparam> abcd_errorbox(n, ABCDparam(Sparam(0.0, 1.0, 1.0, 0.0), z0));
643	
644	
645	        for(unsigned int i=0;i<x;i++) {
646	            // INPUTS: data_dut, f, abcd_errorbox, n
647	
648	            // define the fixture-dut-fixture S-parameters
649	            vector<complex<double>> s_dut;
650	            for(auto s : data_dut) {
651	                s_dut.push_back(s.get(1,1));
652	            }
653	
654	            // define the point for extraction
655	            s_dut.insert(s_dut.begin(), DC2(s_dut, f));
656	            auto dc11 = makeSymmetric(s_dut);
657	            Fft::transform(dc11, true);
658	            makeRealAndScale(dc11);
659	            Fft::shift(dc11, false);
660	            partial_sum(dc11.begin(), dc11.end(), dc11.begin());
661	            auto t11dutStep = dc11;
662	            vector<complex<double>> z11dutStep;
663	            for(auto s : t11dutStep) {
664	                z11dutStep.push_back(-z0 * (s+1.0)/(s-1.0));
665	            }
666	            Fft::shift(z11dutStep, true);
667	            auto zLine = z11dutStep;
668	
669	            // create the TL
670	            auto TL = makeTL(gamma, l, zLine[0], z0);
671	
672	            for(unsigned int i=0;i<n;i++) {
673	                // peel away the the TL
674	                auto abcd_TL = ABCDparam(TL[i], z0);
675	                auto abcd_dut = ABCDparam(data_dut[i], z0);
676	                abcd_dut = abcd_TL.inverse() * abcd_dut;
677	                data_dut[i] = Sparam(abcd_dut, z0);
678	                // add to the errorbox
679	                abcd_errorbox[i] = abcd_errorbox[i] * abcd_TL;
680	            }
681	        }
682	        vector<Sparam> errorbox;
683	        for(auto abcd : abcd_errorbox) {
684	            errorbox.push_back(Sparam(abcd, z0));
685	        }
686	        return hybrid(errorbox, data_2xthru, f);
687	    };
688	
689	    // make the first error box
690	    auto data_side1 = makeErrorbox(data_fix_dut_fix_Sparam, data_2xthru_Sparam, f, gamma, z0);
691	
692	    // reverse the port order of fixture-dut-fixture and 2x thru
693	    vector<Sparam> data_fix_dut_fix_reversed;
694	    for(auto s : data_fix_dut_fix_Sparam) {
695	        s.swapPorts(1,2);
696	        data_fix_dut_fix_reversed.push_back(s);
697	    }
698	    vector<Sparam> data_2xthru_reversed;
699	    for(auto s : data_2xthru_Sparam) {
700	        s.swapPorts(1,2);
701	        data_2xthru_reversed.push_back(s);
702	    }
703	
704	    // make the second error box
705	    auto data_side2 = makeErrorbox(data_fix_dut_fix_reversed, data_2xthru_reversed, f, gamma, z0);
706	
707	    // got the error boxes, convert to T parameters and invert
708	    for(unsigned int i=0;i<f.size();i++) {
709	        Point p;
710	        p.freq = f[i];
711	        p.inverseP1 = Tparam(data_side1[i]).inverse();
712	        // correct port order of error box 2
713	        auto side2 = data_side2[i];
714	        side2.swapPorts(1,2);
715	        p.inverseP2 = Tparam(side2).inverse();
716	        ret.push_back(p);
717	    }
718	    return ret;
719	}
