721	std::vector<DeviceDriver::VNAMeasurement> TwoThru::interpolateEvenFrequencySteps(std::vector<DeviceDriver::VNAMeasurement> input)
722	{
723	    vector<DeviceDriver::VNAMeasurement> ret;
724	    if(input.size() > 1) {
725	        int size = input.size();
726	        double freqStep = 0.0;
727	        if(input.front().frequency == 0) {
728	            freqStep = input[1].frequency;
729	            size--;
730	        } else {
731	            freqStep = input[0].frequency;
732	        }
733	        if(freqStep * size == input.back().frequency) {
734	            // already correct spacing, no interpolation necessary
735	            for(auto d : input) {
736	                if(d.frequency == 0) {
737	                    continue;
738	                }
739	                ret.push_back(d);
740	            }
741	        } else {
742	            // needs to interpolate
743	            double freq = freqStep;
744	            while(freq <= input.back().frequency) {
745	                DeviceDriver::VNAMeasurement interp;
746	                auto it = lower_bound(input.begin(), input.end(), freq, [](const DeviceDriver::VNAMeasurement &lhs, const double f) -> bool {
747	                    return lhs.frequency < f;
748	                });
749	                if(it->frequency == freq) {
750	                    interp = *it;
751	                } else {
752	                    // no exact match, needs to interpolate
753	                    auto high = *it;
754	                    it--;
755	                    auto low = *it;
756	                    double alpha = (freq - low.frequency) / (high.frequency - low.frequency);
757	                    interp = low.interpolateTo(high, alpha);
758	                }
759	                interp.pointNum = it->pointNum;
760	                interp.frequency = freq;
761	                ret.push_back(interp);
762	                freq += freqStep;
763	            }
764	        }
765	    }
766	    return ret;
767	}
