92	void MatchingNetwork::transformDatapoint(DeviceDriver::VNAMeasurement &p)
93	{
94	    if(matching.count(p.frequency) == 0) {
95	        // this point is not calculated yet
96	        MatchingPoint m;
97	        // start with identiy matrix
98	        m.forward = ABCDparam(1.0,0.0,0.0,1.0);
99	        m.reverse = ABCDparam(1.0,0.0,0.0,1.0);
100	        for(unsigned int i=0;i<network.size();i++) {
101	            m.forward = m.forward * network[i]->parameters(p.frequency);
102	            m.reverse = m.reverse * network[network.size()-i-1]->parameters(p.frequency);
103	        }
104	        if(!addNetwork) {
105	            // need to remove the effect of the network, invert matrix
106	            m.forward = m.forward.inverse();
107	            m.reverse = m.reverse.inverse();
108	        }
109	        matching[p.frequency] = m;
110	    }
111	    // at this point the map contains the matching network effect
112	    auto m = matching[p.frequency];
113	    DeviceDriver::VNAMeasurement uncorrected = p;
114	
115	    auto portReflectionName = "S"+QString::number(port)+QString::number(port);
116	    if(!uncorrected.measurements.count(portReflectionName)) {
117	        // the reflection measurement for the port to de-embed is not included, nothing can be done
118	        return;
119	    }
120	    // calculate internal reflection at the matching port
121	    auto portReflectionS = uncorrected.measurements[portReflectionName];
122	    auto matchingReflectionS = Sparam(m.forward, p.Z0).get(2,2);
123	    auto internalPortReflectionS = matchingReflectionS / (1.0 - matchingReflectionS * portReflectionS);
124	
125	    // handle the measurements
126	    for(auto &meas : p.measurements) {
127	        QString name = meas.first;
128	        if(!name.startsWith("S")) {
129	            continue;
130	        }
131	        unsigned int i = name.mid(1,1).toUInt();
132	        unsigned int j = name.mid(2,1).toUInt();
133	        if(i == j) {
134	            // reflection measurement
135	            if(i == port) {
136	                // the port of the matching network itself
137	                auto S = Sparam(uncorrected.measurements[name], 1.0, 1.0, 0.0);
138	                auto corrected = Sparam(m.forward * ABCDparam(S, p.Z0), p.Z0);
139	                p.measurements[name] = corrected.get(1,1);
140	            } else {
141	                // another reflection measurement
142	                try {
143	                    auto S = uncorrected.toSparam().reduceTo({i, port});
144	                    auto corrected = Sparam(ABCDparam(S, p.Z0) * m.reverse, p.Z0);
145	                    p.fromSparam(corrected, {i, port});
146	                } catch (...) {
147	                    // missing measurements, nothing can be done
148	                }
149	            }
150	        } else {
151	            // through measurement
152	            if(i != port && j != port) {
153	                try {
154	                    // find through measurements from these two ports to and from the embedding port
155	                    auto toPort = uncorrected.measurements["S"+QString::number(port)+QString::number(j)];
156	                    auto fromPort = uncorrected.measurements["S"+QString::number(i)+QString::number(port)];
157	                    p.measurements[name] = p.measurements[name] + toPort * internalPortReflectionS * fromPort;
158	                } catch (...) {
159	                    // missing measurements, nothing can be done
160	                }
161	            } else {
162	                // Already handled by reflection measurement (toSparam uses S12/S21 as well)
163	                // and if the corresponding reflection measurement is not available, we can't
164	                // do anything anyway
165	            }
166	        }
167	    }
168	}
