262	void MatchingNetwork::fromJSON(nlohmann::json j)
263	{
264	    clearNetwork();
265	    port = j.value("port", 1);
266	    if(j.contains("network")) {
267	        for(auto jc : j["network"]) {
268	            if(!jc.contains("component")) {
269	                continue;
270	            }
271	            auto c = MatchingComponent::createFromName(QString::fromStdString(jc["component"]));
272	            if(!c) {
273	                continue;
274	            }
275	            c->fromJSON(jc["params"]);
276	            network.push_back(c);
277	        }
278	    }
279	    addNetwork = j.value("addNetwork", true);
280	    matching.clear();
281	    updateSCPINames();
