293	MatchingComponent *MatchingNetwork::componentAtPosition(int pos)
294	{
295	    pos -= graph->layout()->itemAt(0)->geometry().width();
296	    pos -= portWidth;
297	    if(pos > 0 && pos <= (int) network.size() * componentWidth) {
298	        // position is in port 1 network
299	        return network[pos / componentWidth];
300	    }
301	    return nullptr;
302	}
