304	unsigned int MatchingNetwork::findInsertPosition(int xcoord)
305	{
306	    xcoord -= graph->layout()->itemAt(0)->geometry().width();
307	    xcoord -= portWidth;
308	    // added in port 1 network
309	    int index = (xcoord + componentWidth / 2) / componentWidth;
310	    if(index < 0) {
311	        index = 0;
312	    } else if(index > (int) network.size()) {
313	        index = network.size();
314	    }
315	    // add 2 (first two widgets are always the stretch and port 1 widget)
316	    return index + 2;
317	}
