319	void MatchingNetwork::addComponentAtPosition(int pos, MatchingComponent *c)
320	{
321	    auto index = findInsertPosition(pos);
322	    QHBoxLayout *l = static_cast<QHBoxLayout*>(graph->layout());
323	    l->insertWidget(index, c);
324	    c->show();
325	
326	    // add component to correct matching network
327	    index -= 2; // first two widgets are fixed
328	    addComponent(index, c);
329	
330	    // network changed, need to recalculate matching
331	    matching.clear();
332	    connect(c, &MatchingComponent::valueChanged, [=](){
333	       matching.clear();
334	    });
