394	bool MatchingNetwork::eventFilter(QObject *object, QEvent *event)
395	{
396	    if(object->objectName() == "Graph") {
397	        if(event->type() == QEvent::MouseButtonPress) {
398	            auto mouseEvent = static_cast<QMouseEvent*>(event);
399	            if (mouseEvent->button() == Qt::LeftButton) {
400	                dragComponent = componentAtPosition(mouseEvent->pos().x());
401	                if(dragComponent) {
402	                    dragStartPosition = mouseEvent->pos();
403	                    return true;
404	                }
405	            }
406	            return false;
407	        } else if(event->type() == QEvent::MouseMove) {
408	            auto mouseEvent = static_cast<QMouseEvent*>(event);
409	            if (!(mouseEvent->buttons() & Qt::LeftButton)) {
410	                return false;
411	            }
412	            if (!dragComponent) {
413	                return false;
414	            }
415	            if ((mouseEvent->pos() - dragStartPosition).manhattanLength()
416	                 < QApplication::startDragDistance()) {
417	                return false;
418	            }
419	
420	            // remove and hide component while it is being dragged
421	            graph->layout()->removeWidget(dragComponent);
422	            dragComponent->hide();
423	            removeComponent(dragComponent);
424	            graph->update();
425	
426	            // network changed, need to recalculate matching
427	            matching.clear();
428	
429	            createDragComponent(dragComponent);
430	            return true;
431	        } else if(event->type() == QEvent::DragEnter) {
432	            auto dragEvent = static_cast<QDragEnterEvent*>(event);
433	            if(dragEvent->mimeData()->hasFormat("matchingComponent/pointer")) {
434	                dropPending = true;
435	                auto data = dragEvent->mimeData()->data("matchingComponent/pointer");
436	                QDataStream stream(&data, QIODevice::ReadOnly);
437	                quintptr dropPtr;
438	                stream >> dropPtr;
439	                dropComponent = (MatchingComponent*) dropPtr;
440	                dragEvent->acceptProposedAction();
441	                insertIndicator = new QWidget();
442	                insertIndicator->setMinimumSize(2, imageHeight);
443	                insertIndicator->setMaximumSize(2, imageHeight);
444	                insertIndicator->setSizePolicy(QSizePolicy::Fixed, QSizePolicy::Fixed);
445	                insertIndicator->setStyleSheet("background-color:red;");
446	                updateInsertIndicator(dragEvent->position().toPoint().x());
447	                return true;
448	            }
449	        } else if(event->type() == QEvent::DragMove) {
450	            auto dragEvent = static_cast<QDragMoveEvent*>(event);
451	            updateInsertIndicator(dragEvent->position().toPoint().x());
452	            return true;
453	        } else if(event->type() == QEvent::Drop) {
454	            auto dragEvent = static_cast<QDropEvent*>(event);
455	            delete insertIndicator;
456	            addComponentAtPosition(dragEvent->position().toPoint().x(), dropComponent);
457	            return true;
458	        } else if(event->type() == QEvent::DragLeave) {
459	            dropPending = false;
460	            dropComponent = nullptr;
461	            delete insertIndicator;
462	        }
463	    } else {
464	        // clicked/dragged one of the components outside of the graph
465	        if(event->type() == QEvent::MouseButtonPress) {
466	            auto mouseEvent = static_cast<QMouseEvent*>(event);
467	            if (mouseEvent->button() == Qt::LeftButton) {
468	                dragStartPosition = mouseEvent->pos();
469	                if(object->objectName() == "lSeriesC") {
470	                    dragComponent = new MatchingComponent(MatchingComponent::Type::SeriesC);
471	                } else if(object->objectName() == "lSeriesL") {
472	                    dragComponent = new MatchingComponent(MatchingComponent::Type::SeriesL);
473	                } else if(object->objectName() == "lSeriesR") {
474	                    dragComponent = new MatchingComponent(MatchingComponent::Type::SeriesR);
475	                } else if(object->objectName() == "lParallelC") {
476	                    dragComponent = new MatchingComponent(MatchingComponent::Type::ParallelC);
477	                } else if(object->objectName() == "lParallelL") {
478	                    dragComponent = new MatchingComponent(MatchingComponent::Type::ParallelL);
479	                } else if(object->objectName() == "lParallelR") {
480	                    dragComponent = new MatchingComponent(MatchingComponent::Type::ParallelR);
481	                } else if(object->objectName() == "lDefinedThrough") {
482	                    dragComponent = new MatchingComponent(MatchingComponent::Type::DefinedThrough);
483	                } else if(object->objectName() == "lDefinedShunt") {
484	                    dragComponent = new MatchingComponent(MatchingComponent::Type::DefinedShunt);
485	                } else {
486	                    dragComponent = nullptr;
487	                }
488	                return true;
489	            }
490	            return false;
491	        } else if(event->type() == QEvent::MouseMove) {
492	            auto mouseEvent = static_cast<QMouseEvent*>(event);
493	            if (!(mouseEvent->buttons() & Qt::LeftButton)) {
494	                return false;
495	            }
496	            if (!dragComponent) {
497	                return false;
498	            }
499	            if ((mouseEvent->pos() - dragStartPosition).manhattanLength()
500	                 < QApplication::startDragDistance()) {
501	                return false;
502	            }
503	
504	            createDragComponent(dragComponent);
505	            return true;
506	        }
507	    }
508	    return false;
509	}
