511	void MatchingNetwork::updateSCPINames()
512	{
513	    // Need to remove all components from the subnode list first, otherwise
514	    // name changes wouldn't work due to temporarily name collisions
515	    for(auto &c : network) {
516	        remove(c);
517	    }
518	    unsigned int i=1;
519	    for(auto &c : network) {
520	        c->changeName(QString::number(i));
521	        add(c);
522	        i++;
523	    }
524	}
