620	        touchstoneLabel->setAlignment(Qt::AlignCenter);
621	        auto layout = new QVBoxLayout();
622	        layout->addWidget(touchstoneLabel);
623	        layout->setContentsMargins(0, 0, 0, 0);
624	        setLayout(layout);
625	        setStyleSheet("image: url(:/icons/definedShunt.png);");
626	        updateTouchstoneLabel();
627	    }
628	        break;
629	    default:
630	        break;
631	    }
632	    switch(type) {
633	    case Type::SeriesR:
634	    case Type::SeriesL:
635	    case Type::SeriesC:
636	    case Type::ParallelR:
637	    case Type::ParallelL:
638	    case Type::ParallelC:
639	        addDoubleParameter("VALue", value, true, true, [=](){
640	            eValue->setValue(value);
641	        });
642	        break;
643	    case Type::DefinedThrough:
644	    case Type::DefinedShunt:
645	        add(new SCPICommand("FILE", [=](QStringList params) -> QString {
646	            if(params.size() < 1) {
647	                return SCPI::getResultName(SCPI::Result::Error);
648	            }
649	            try {
650	                *touchstone = Touchstone::fromFile(params[0].toStdString());
651	                updateTouchstoneLabel();
652	                emit valueChanged();
653	                return SCPI::getResultName(SCPI::Result::Empty);
654	            } catch(const std::exception& e) {
655	                // failed to load file
656	                return SCPI::getResultName(SCPI::Result::Error);
657	            }
658	        }, nullptr, false));
659	        break;
660	    default:
661	        break;
662	    }
663	}
