672	ABCDparam MatchingComponent::parameters(double freq)
673	{
674	    switch(type) {
675	    case Type::SeriesR:
676	        return ABCDparam(1.0, eValue->value(), 0.0, 1.0);
677	    case Type::SeriesL:
678	        return ABCDparam(1.0, complex<double>(0, freq * 2 * M_PI * eValue->value()), 0.0, 1.0);
679	    case Type::SeriesC:
680	        return ABCDparam(1.0, complex<double>(0, -1.0 / (freq * 2 * M_PI * eValue->value())), 0.0, 1.0);
681	    case Type::ParallelR:
682	        return ABCDparam(1.0, 0.0, 1.0/eValue->value(), 1.0);
683	    case Type::ParallelL:
684	        return ABCDparam(1.0, 0.0, 1.0/complex<double>(0, freq * 2 * M_PI * eValue->value()), 1.0);
685	    case Type::ParallelC:
686	        return ABCDparam(1.0, 0.0, 1.0/complex<double>(0, -1.0 / (freq * 2 * M_PI * eValue->value())), 1.0);
687	    case Type::DefinedThrough:
688	        if(touchstone->points() == 0 || freq < touchstone->minFreq() || freq > touchstone->maxFreq()) {
689	            // outside of provided frequency range, pass through unchanged
690	            return ABCDparam(1.0, 0.0, 0.0, 1.0);
691	        } else {
692	            auto d = touchstone->interpolate(freq);
693	            auto S = Sparam(d.S[0], d.S[1], d.S[2], d.S[3]);
694	            return ABCDparam(S, touchstone->getReferenceImpedance());
695	        }
696	    case Type::DefinedShunt:
697	        if(touchstone->points() == 0 || freq < touchstone->minFreq() || freq > touchstone->maxFreq()) {
698	            // outside of provided frequency range, pass through unchanged
699	            return ABCDparam(1.0, 0.0, 0.0, 1.0);
700	        } else {
701	            auto d = touchstone->interpolate(freq);
702	            auto Y = Yparam(Sparam(d.S[0], d.S[1], d.S[2], d.S[3]), touchstone->getReferenceImpedance());
703	            return ABCDparam(1.0, 0.0, Y.get(1,1), 1.0);
704	        }
705	    default:
706	        return ABCDparam(1.0, 0.0, 0.0, 1.0);
707	    }
708	}
