1	#ifndef TPARAM_H
2	#define TPARAM_H
3	
4	#include "savable.h"
5	
6	#include <complex>
7	
8	#include "Eigen/Dense"
9	
10	using Type = std::complex<double>;
11	
12	class Parameters : public Savable {
13	public:
14	    Parameters(Type m11);
15	    Parameters(Type m11, Type m12, Type m21, Type m22);
16	    Parameters(int num_ports);
17	    Parameters() : Parameters(2){}
18	
19	    Eigen::MatrixXcd data;
20	
21	    unsigned int ports() const { return data.cols();}
22	
23	    // Access to elements is usually off-by-one (mostly 1-based indexing in literature but Eigen uses 0-based indexing)
24	    Type get(unsigned int row, unsigned int col) const {return data(row-1, col-1);}
25	    void set(unsigned int row, unsigned int col, Type t) { data(row-1, col-1) = t;}
26	
27	    nlohmann::json toJSON() override;
28	    void fromJSON(nlohmann::json j) override;
29	};
30	
31	// forward declaration of parameter classes
32	class Sparam;
33	class Zparam;
34	class Yparam;
35	class Tparam;
36	class ABCDparam;
37	
38	class Sparam : public Parameters {
39	public:
40	    using Parameters::Parameters;
41	    Sparam(const Tparam &t);
42	    Sparam(const ABCDparam &a, Type Z01, Type Z02);
43	    Sparam(const ABCDparam &a, Type Z0);
44	    Sparam(const Zparam &Z, std::vector<Type> Z0n);
45	    Sparam(const Zparam &Z, Type Z0);
46	    Sparam operator+(const Sparam &r) const {
47	        Sparam p(ports());
48	        p.data = data+r.data;
49	        return p;
50	    }
51	    Sparam operator*(const Type &r) const {
52	        Sparam p(ports());
53	        p.data = data * r;
54	        return p;
55	    }
56	    void swapPorts(unsigned int p1, unsigned int p2);
57	    // reduces the S parameter matrix to specified ports.
58	    // Example: 4 port S parameters as an input but we want the 2 port data from the original ports 1 and 3
59	    // Call: S.reduceTo(1, 3)
60	    // Result: 2 port S parameters (S11, S12, S21, S22) which are set to the original (S11, S13, S31, S33)
61	    Sparam reduceTo(std::vector<unsigned int> ports) const;
62	};
63	
64	class Zparam : public Parameters {
65	public:
66	    using Parameters::Parameters;
67	    Zparam(int num_ports) : Parameters(num_ports){}
68	    Zparam(const Sparam &S, std::vector<Type> Z0n);
69	    Zparam(const Sparam &S, Type Z0);
70	    Zparam(const Yparam &Y);
71	};
72	
73	class ABCDparam : public Parameters {
74	public:
75	    using Parameters::Parameters;
76	    ABCDparam() : Parameters(2){}
77	    ABCDparam(const Sparam &s, Type Z01, Type Z02);
78	    ABCDparam(const Sparam &s, Type Z0);
79	    ABCDparam operator*(const ABCDparam &r) {
80	        ABCDparam p;
81	        // ABCD parameters can be multiplied by matrix multiplication
82	        p.data = data * r.data;
83	        return p;
84	    }
85	    ABCDparam inverse() {
86	        ABCDparam i;
87	        // by hand, this is faster because the Eigen matrix is using dynamic size
88	        Type det = data(0,0)*data(1,1) - data(0,1)*data(1,0);
89	        i.data(0,0) = data(1,1) / det;
90	        i.data(0,1) = -data(0,1) / det;
91	        i.data(1,0) = -data(1,0) / det;
92	        i.data(1,1) = data(0,0) / det;
93	        return i;
94	    }
95	    ABCDparam operator*(const Type &r) const {
96	        ABCDparam p;
97	        p.data = data * r;
98	        return p;
99	    }
100	    ABCDparam root() {
101	        // calculate root of 2x2 matrix, according to https://en.wikipedia.org/wiki/Square_root_of_a_2_by_2_matrix (choose positive roots)
102	        auto tau = data(0,0) + data(1,1);
103	        auto sigma = data(0,0)*data(1,1) - data(0,1)*data(1,0);
104	        auto s = sqrt(sigma);
105	        auto t = sqrt(tau + 2.0*s);
106	        ABCDparam r = *this;
107	        r.data(0,0) += s;
108	        r.data(1,1) += s;
109	        r.data = r.data * (1.0/t);
110	        return r;
111	    }
112	};
113	
114	class Tparam : public Parameters {
115	public:
116	    using Parameters::Parameters;
117	    Tparam(const Sparam &s);
118	    Tparam operator*(const Tparam &r) {
119	        Tparam p;
120	        // T parameters can be multiplied by matrix multiplication
121	        p.data = data * r.data;
122	        return p;
123	    }
124	    Tparam operator+(const Tparam &r) {
125	        Tparam p;
126	        p.data = data + r.data;
127	        return p;
128	    }
129	    Tparam inverse() {
130	        Tparam i;
131	        Type det = data(0,0)*data(1,1) - data(0,1)*data(1,0);
132	        i.data(0,0) = data(1,1) / det;
133	        i.data(0,1) = -data(0,1) / det;
134	        i.data(1,0) = -data(1,0) / det;
135	        i.data(1,1) = data(0,0) / det;
136	        return i;
137	    }
138	    Tparam operator*(const Type &r) {
139	        Tparam p;
140	        p.data = data * r;
141	        return p;
142	    }
143	    Tparam operator*(const double &r) {
144	        Tparam p;
145	        p.data = data * r;
146	        return p;
147	    }
148	    Tparam root() {
149	        // calculate root of 2x2 matrix, according to https://en.wikipedia.org/wiki/Square_root_of_a_2_by_2_matrix (choose positive roots)
150	        auto tau = data(0,0) + data(1,1);
