214	                used_ports.insert(upper_bound(used_ports.begin(), used_ports.end(), i), i);
215	            } else {
216	                // remove port from the vector
217	                used_ports.erase(std::remove(used_ports.begin(), used_ports.end(), i), used_ports.end());
218	            }
219	            QTimer::singleShot(0, [=](){
220	                createGUI();
221	                setInitialChoices();
222	            });
223	        });
224	        formlayout->addRow(label, cb);
225	    }
226	    for(unsigned int i=0;i<used_ports.size();i++) {
227	        for(unsigned int j=0;j<used_ports.size();j++) {
228	            auto label = new QLabel("S"+QString::number(used_ports[i])+QString::number(used_ports[j])+":");
229	            auto box = new QComboBox();
230	            connect(box, qOverload<int>(&QComboBox::currentIndexChanged), [=](int) {
231	               traceSelectionChanged(box);
232	            });
233	            boxes.push_back(box);
234	            formlayout->addRow(label, box);
235	        }
236	    }
237	
238	    scroll->setWidget(w);
239	    w->show();
240	    eventFilter(scroll, new QEvent(QEvent::Resize));
241	}
