243	bool SparamTraceSelector::eventFilter(QObject *watched, QEvent *event)
244	{
245	    // Make sure that the widget in the scroll area always expands to the scroll area size horizontally (only vertical scrolling)
246	    if(event->type() == QEvent::Resize) {
247	        auto scroll = (QScrollArea*) watched;
248	        auto w = scroll->widget();
249	        auto width = scroll->width();
250	        if(scroll->verticalScrollBar()->isVisible()) {
251	            width -= scroll->verticalScrollBar()->width();
252	        }
253	        w->setFixedWidth(width);
254	    }
255	    return false;
256	}
